const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={group:'M3 20v-2a4 4 0 0 1 4-4h4a4 4 0 0 1 4 4v2M17 14a4 4 0 0 1 4 4v2M9 10a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM17 4a3 3 0 0 1 0 6',record:'M12 8v8M8 12h8M6 3h12a3 3 0 0 1 3 3v12a3 3 0 0 1-3 3H6a3 3 0 0 1-3-3V6a3 3 0 0 1 3-3Z',analysis:'M4 20V10m8 10V4m8 16v-7M2 21h20',me:'M4 20V10m8 10V4m8 16v-7M2 21h20'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.group}"/></svg>`;
const blank=()=>({page:'home',room:null,members:[],records:{},role:'host',today:new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),remindRead:false});
let state;try{state=JSON.parse(localStorage.getItem('qingyou-v1'))||blank()}catch{state=blank()}let selected=0,range=28,unit='kg',groupMetric='change',groupRange=28,goalFail=false,inviteState='normal',draft={name:'',intro:'',days:14,intensity:'低'};
const save=()=>localStorage.setItem('qingyou-v1',JSON.stringify(state));const me=()=>state.members[0];const dateAdd=(s,n)=>{let d=new Date(s+'T12:00:00+08:00');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};const end=()=>dateAdd(state.room.start,state.room.days-1);const dayCount=()=>state.room?.start?Math.min(state.room.days,Math.max(1,Math.round((new Date(state.today+'T12:00:00+08:00')-new Date(state.room.start+'T12:00:00+08:00'))/86400000)+1)):0;
const btn=(label,action,cls='',disabled=false)=>`<button class="btn ${cls}" ${disabled?'disabled':''} onclick="${action}">${label}</button>`;const badge=(text,cls='')=>`<span class="badge ${cls}">${text}</span>`;const avatar=(m,i)=>`<span class="avatar ${['','blue','orange','purple'][i%4]}">${esc(m.name.slice(-1))}</span>`;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function go(p){state.page=p;save();render();window.scrollTo(0,0)}function closeModal(){$('#overlay').innerHTML='';pendingRoom=null}
function modal(title,body,actions='',options={}){ $('#overlay').innerHTML=`<div class="modal-shade" onclick="if(event.target===this)closeModal()"><section class="modal ${esc(options.className||'')}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="row"><h2>${title}</h2>${options.hideClose?'':'<button class="close" onclick="closeModal()" aria-label="关闭">×</button>'}</div>${body}${actions}</section></div>`;$('#overlay button')?.focus()}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
function shell(content,form=false){const nav=state.room&&state.room.status!=='lobby';return `<div class="layout page-${state.page} ${form?'form-layout':''}"><aside class="sidebar"><div class="brand"><span>秤群结队</span></div>${nav?`<nav class="nav" aria-label="主导航">${[['group','小组'],['record','记录'],['me','数据']].map(([id,t])=>`<button class="${(state.page===id||(id==='group'&&state.page==='analysis'))?'active':''}" onclick="go('${id}')">${icon(id)}${t}</button>`).join('')}</nav>`:''}</aside><main>${content}</main></div>`}
const head=(title,sub='',right='')=>`<header class="page-head"><div><h1>${title}</h1>${sub?`<p class="sub">${sub}</p>`:''}</div>${right}</header>`;
function render(){let c='';if(state.page==='home'){ $('#app').innerHTML=`<main class="hero-home"><h1>秤群结队</h1><div class="home-actions">${btn('创建小组',"go('create')",'full')}${btn('加入小组',"inviteState='normal';go('join')",'secondary full')}</div></main>`;return}
if(state.page==='create')c=createPage();else if(state.page==='join')c=joinPage();else if(state.page==='invite')c=invitePage();else if(state.page==='lobby')c=lobbyPage();else if(state.page==='group')c=state.room.status==='ended'?reviewPage():groupPage();else if(state.page==='record')c=recordPage();else if(state.page==='analysis')c=analysisPage();else if(state.page==='me')c=mePage();$('#app').innerHTML=shell(c,['create','join','invite','lobby'].includes(state.page))}
function backButton(page,label){return `<button type="button" class="back" aria-label="${label}" onclick="go('${page}')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m14 6-6 6 6 6"/></svg><span>${label}</span></button>`}
function createPage(){return `<div class="form-shell create-page">${backButton('home','返回首页')}${head('创建小组')}<form class="card create-form" onsubmit="event.preventDefault();createRoom()"><label class="field"><span class="field-label">小组名称<span class="optional">选填</span></span><input id="roomName" placeholder="晚饭后散步小队" maxlength="24" value="${esc(draft.name)}" oninput="draft.name=this.value"><span id="nameError" class="error"></span></label><label class="field"><span class="field-label">小组介绍<span class="optional">选填</span></span><textarea placeholder="比如：晚饭后一起走走，认真记录每一天。" oninput="draft.intro=this.value">${esc(draft.intro)}</textarea></label><fieldset class="field period-field"><legend class="field-label">本期天数</legend>${periodOptions()}<div id="dayError" class="error"></div></fieldset><div class="field"><span class="field-label">减肥强度</span><div class="triple">${['低','中','高'].map((v,i)=>`<button type="button" class="choice ${draft.intensity===v?'active':''}" aria-pressed="${draft.intensity===v}" onclick="chooseIntensity('${v}')">${v}<small>${['轻松记录','适度挑战','谨慎选择'][i]}</small></button>`).join('')}</div></div><div class="page-action-bar">${btn('创建',"",'full')}</div></form></div>`}
function periodOptions(){return `<div class="triple period-options">${[14,28,56].map(n=>`<button type="button" class="period-choice ${!draft.customDays&&Number(draft.days)===n?'active':''}" aria-pressed="${!draft.customDays&&Number(draft.days)===n}" onclick="chooseDays(${n})"><span class="period-value">${n}<span>天</span></span><span class="period-check" aria-hidden="true">${!draft.customDays&&Number(draft.days)===n?'✓':''}</span></button>`).join('')}<label class="period-choice period-custom ${draft.customDays?'active':''}" id="customDaysOption"><input id="customDays" aria-label="自定义天数" type="text" inputmode="numeric" autocomplete="off" placeholder="自定义" value="${esc(draft.customValue??'')}" onfocus="chooseCustomDays()" oninput="updateCustomDays(this)" onblur="validateCustomDays(this,event)"><span class="custom-days-unit" ${draft.customValue?'':'hidden'}>天</span><span class="period-check" aria-hidden="true">${draft.customDays?'✓':''}</span></label></div>`}
function chooseDays(n){if(![14,28,56].includes(n))return;draft.customDays=false;draft.days=n;render()}
function chooseCustomDays(){draft.customDays=true;draft.days=$('#customDays').value;document.querySelectorAll('.period-options button').forEach(button=>{button.classList.remove('active');button.setAttribute('aria-pressed','false');button.querySelector('.period-check').textContent=''});$('#customDaysOption').classList.add('active');$('#customDaysOption .period-check').textContent='✓'}
function updateCustomDays(input){draft.days=input.value;draft.customValue=input.value;$('#customDaysOption .custom-days-unit').hidden=input.value==='';$('#dayError').textContent='';input.setAttribute('aria-invalid','false')}
function validateCustomDays(input,event){if(event?.relatedTarget?.closest('.period-options button'))return;const invalid=!/^\d+$/.test(input.value)||!Number.isInteger(Number(input.value))||Number(input.value)<14||Number(input.value)>90;input.setAttribute('aria-invalid',String(invalid));if(invalid)toast('天数不合法，请输入 14–90 之间的整数');return !invalid}
function chooseIntensity(v){if(v==='高')modal('选择高强度','<p>高强度意味着更高的目标要求，请谨慎选择。</p>',btn('我已了解，选择高强度',"draft.intensity='高';closeModal();render()",'full')+`<button class="cancel" onclick="closeModal()">暂不选择</button>`);else{draft.intensity=v;render()}}
let pendingRoom=null;
function createRoom(){const n=Number(draft.days);if((draft.customDays&&!/^\d+$/.test(String(draft.days)))||!Number.isInteger(n)||n<14||n>90){toast('天数不合法，请输入 14–90 之间的整数');$('#customDays')?.focus();return}pendingRoom={name:draft.name.trim()||'晚饭后散步小队',intro:draft.intro.trim(),days:n,intensity:draft.intensity,status:'lobby'};modal('确认创建小组',`<p>请确认小组信息，准备好后就可以邀请朋友加入。</p><dl class="create-summary"><div><dt>小组名称</dt><dd>${esc(pendingRoom.name)}</dd></div><div><dt>本期天数</dt><dd>${n}<span> 天</span></dd></div><div><dt>减肥强度</dt><dd><span class="badge">${esc(pendingRoom.intensity)}强度</span></dd></div></dl><p class="create-date-note">起止日期将在房主点击“开始本期”时确定。</p>`,btn('确认创建',"confirmCreateRoom()",'full')+`<button class="cancel" onclick="pendingRoom=null;closeModal()">返回修改</button>`)}
function confirmCreateRoom(){if(!pendingRoom)return;const room=pendingRoom;pendingRoom=null;state={...blank(),room,members:[{name:'林可',ready:false}],role:'host'};closeModal();go('lobby')}
function joinPage(){return `<div class="form-shell">${backButton('home','返回首页')}${head('加入小组')}<form class="card" onsubmit="event.preventDefault();openInvite()"><label class="field"><span class="field-label">小组邀请码</span><input id="inviteCode" placeholder="输入邀请码" autocomplete="off" maxlength="12"><div class="error" id="inviteError"></div></label><div class="page-action-bar">${btn('查看小组',"",'full')}</div></form></div>`}
function openInvite(){if(!$('#inviteCode').value.trim()){$('#inviteError').textContent='请输入邀请码';return}inviteState=$('#inviteCode').value.trim().toUpperCase()==='QY2026'?'normal':'invalid';go('invite')}
function invitePage(){return `<div class="form-shell">${backButton('join','返回')}${head('加入小组')}<div class="card"><span class="badge">${inviteState==='invalid'?'邀请已失效':'等待开营'}</span><h2 style="margin-top:18px">晚饭后散步小队</h2><div class="row" style="margin:24px 0"><div class="person">${avatar({name:'阿宁'},1)}${avatar({name:'小周'},2)}</div><small>${inviteState==='full'?'8':'2'} / 8 位成员 · 21 天 · 低强度</small></div><div class="notice">加入后才能查看组员的体重和趋势。</div></div><div class="card"><h3>一起开始前，请先了解</h3><p class="sub" style="margin-top:16px">本期体重和趋势对所有组员可见，包括之后加入的成员。</p><p class="sub" style="margin-top:12px">开营后至结束不能中途退出，房主也不能提前关闭。</p><label class="check"><input id="agree" type="checkbox" onchange="$('#joinBtn').disabled=!this.checked||inviteState!=='normal'"><span>我已了解并同意上述组内可见与参与规则</span></label><button id="joinBtn" class="btn full" disabled onclick="joinRoom()">${inviteState==='full'?'小组已满员':inviteState==='invalid'?'邀请已失效':'确认加入'}</button>${inviteState!=='normal'?'<p class="sub">当前无法加入，请联系邀请人。</p>':''}</div></div>`}
function joinRoom(){if(inviteState!=='normal'){toast('当前邀请不可加入');return}state={...blank(),role:'member',room:{name:'晚饭后散步小队',intro:'不急着改变，先把每一天记录下来。',days:21,intensity:'低',status:'lobby'},members:[{name:'林可',ready:false},{name:'阿宁',ready:true,weight:65,target:64.58},{name:'小周',ready:true,weight:78,target:77.58}]};go('lobby')}
function lobbyPage(){if(!state.room)return '';let r=state.room,m=me(),ready=state.members.every(m=>m.ready),can=state.members.length>=2&&ready&&state.role==='host';return `<div class="form-shell lobby-page">${backButton('home','返回首页')}${head(esc(r.name),`${r.days} 天 · ${r.intensity}强度`,badge('待开始'))}${r.intro?`<p class="sub" style="margin:-10px 0 24px">${esc(r.intro)}</p>`:''}<section class="card"><div class="row section-head"><h2>小组成员 <small>${state.members.length} / 8</small></h2><button class="text-btn" onclick="invite()" ${state.members.length>=8?'disabled':''}>邀请好友 ↗</button></div>${state.members.map((x,i)=>`<div class="member row"><div class="person">${avatar(x,i)}<div><span class="member-name">${esc(x.name)}${i===0?'（我）':''}</span>${(state.role==='host'?i===0:i===1)?badge('房主'):''}${i===0?`<p class="sub member-goal">${x.ready?'目标 '+x.target.toFixed(2)+' kg':'&nbsp;'}</p>`:''}</div></div>${badge(x.ready?'✓ 已准备':'未准备',x.ready?'':'amber')}</div>`).join('')}</section><section class="card"><div class="row"><h2>我的准备</h2>${badge(m.ready?'✓ 已准备':'未准备',m.ready?'':'amber')}</div><div class="preparation-body">${m.ready?`<div class="ready-result"><small>本期目标体重</small><div class="big" style="margin:8px 0">${m.target.toFixed(2)}<span class="unit">kg</span></div><p class="sub">身高 ${m.height} cm · 起始 ${m.weight.toFixed(2)} kg</p><button type="button" class="text-btn edit-preparation" onclick="editPreparation()">修改身高体重</button></div>`:`<div class="compare" style="margin-bottom:14px"><label><span class="field-label">真实身高 <small>cm</small></span><input id="height" type="number" value="${esc(m.height??'')}" placeholder="如 168" inputmode="decimal"><div id="heightError" class="error"></div></label><label><span class="field-label">起始体重 <small>kg</small></span><input id="startWeight" type="number" step="0.01" value="${m.weight!=null?esc(Number(m.weight).toFixed(2)):''}" placeholder="如 70.00" inputmode="decimal"><div id="weightError" class="error"></div></label></div>${btn('生成目标体重',"generateGoal()",'soft full')}`}</div></section><div class="page-action-bar lobby-action-bar">${btn(state.role==='host'?'开始本期':'等待房主开始',"startConfirm()",'full',!can)}<p class="sub" style="text-align:center">${state.role!=='host'?'准备完成后，等待房主发起本期。':state.members.length<2?'至少 2 人才能开始本期':!ready?`还有 ${state.members.filter(m=>!m.ready).length} 位成员未准备`:''}</p></div>${state.role==='member'?`<button class="text-btn" onclick="go('home')">取消加入</button>`:''}</div>`}
function addFriend(){if(state.members.length>=8){toast('小组已满员');return}state.members.push({name:['阿宁','小周','小林','小许','小陈','小叶','小方'][state.members.length-1],ready:false});save();render()}
function readyOthers(){state.members.slice(1).forEach(m=>Object.assign(m,{ready:true,weight:65,target:64.58,height:168}));save();render()}
// Replaceable illustration only: height is collected, not used as a clinical assessment.
function demoGoal(weight,intensity,days){return Math.max(1,weight-({低:.02,中:.035,高:.05}[intensity]*days))}
function editPreparation(){if(state.room?.status!=='lobby')return;const m=me();modal('修改身高体重',`<div class="compare preparation-fields"><label for="height"><span class="field-label">身高 <small>cm</small></span><input id="height" type="number" inputmode="decimal" value="${esc(m.height)}" aria-describedby="heightError"><div id="heightError" class="error"></div></label><label for="startWeight"><span class="field-label">起始体重 <small>kg</small></span><input id="startWeight" type="number" step="0.01" inputmode="decimal" value="${esc(m.weight.toFixed(2))}" aria-describedby="weightError"><div id="weightError" class="error"></div></label></div>`,`<div class="preparation-actions">${btn('保存修改',"savePreparation()",'full')}<button type="button" class="cancel" onclick="closeModal()">取消</button></div>`);$('#overlay .modal-shade').classList.add('preparation-sheet')}
function savePreparation(){if(state.room?.status!=='lobby')return;const h=Number($('#height').value),w=Number($('#startWeight').value),heightValid=Number.isFinite(h)&&h>=80&&h<=250,weightValid=Number.isFinite(w)&&w>=20&&w<=300;$('#heightError').textContent=heightValid?'':'请输入 80–250 cm 的身高';$('#weightError').textContent=weightValid?'':'请输入 20–300 kg 的体重';$('#height').setAttribute('aria-invalid',String(!heightValid));$('#startWeight').setAttribute('aria-invalid',String(!weightValid));if(!heightValid||!weightValid){$(heightValid?'#startWeight':'#height').focus();return}if(goalFail){toast('目标生成失败，请重试');return}Object.assign(me(),{height:h,weight:w,target:demoGoal(w,state.room.intensity,state.room.days),ready:true});save();closeModal();render();toast('身高体重已更新')}
function generateGoal(){let h=Number($('#height').value),w=Number($('#startWeight').value);$('#heightError').textContent=h>=80&&h<=250?'':'请输入 80–250 cm 的身高';$('#weightError').textContent=w>=20&&w<=300?'':'请输入 20–300 kg 的体重';if(!Number.isFinite(h)||!Number.isFinite(w)||h<80||h>250||w<20||w>300)return;if(goalFail){toast('目标生成失败，请重试');return}Object.assign(me(),{ready:true,height:h,weight:w,target:demoGoal(w,state.room.intensity,state.room.days)});save();render();toast('目标已生成，准备完成')}
function startConfirm(){if(!canStart())return;const today=blank().today,last=dateAdd(today,state.room.days-1),format=d=>`${Number(d.slice(5,7))} 月 ${Number(d.slice(8,10))} 日`;modal('确认开始本期',`<section class="start-period" aria-label="本期起止日期"><div class="start-period-heading"><span>本期记录</span><span class="badge">${state.room.days} 天</span></div><div class="start-period-dates"><div><span class="start-date-label">开始</span><strong>${format(today)}</strong><small>${today.slice(0,4)} 年 · 今天</small></div><span class="start-date-connector" aria-hidden="true"></span><div><span class="start-date-label">结束</span><strong>${format(last)}</strong><small>${last.slice(0,4)} 年 · 23:59 截止</small></div></div></section><p class="start-confirm-note">从今天开始记录。开始后成员不能中途退出，房主也不能提前关闭。</p>`,btn('确认开始',`startRoom('${today}')`,'full')+`<button class="cancel" onclick="closeModal()">再等等</button>`);$('#overlay .modal').classList.add('start-confirm-modal')}
function canStart(){return state.room.status==='lobby'&&state.role==='host'&&state.members.length>=2&&state.members.every(m=>m.ready)}
function startRoom(shown){if(!canStart()){closeModal();render();toast('开营条件已变化，请重新检查');return}if(shown!==blank().today){startConfirm();return}state.room.start=shown;state.room.status='active';state.today=shown;state.members.forEach((m,i)=>{m.join=shown;state.records[i]=[]});closeModal();go('group');toast('本期已开始')}
function invite(){if(state.members.length>=8){toast('小组已满员');return}modal('邀请好友',`<p>把邀请码分享给朋友，一起加入小队。</p><div class="code">QY2026</div>`,btn('复制邀请信息',"copyInvite()",'full'))}
async function copyInvite(){try{await navigator.clipboard.writeText('秤群结队 · '+state.room.name+'，邀请码 QY2026');toast('邀请信息已复制')}catch{toast('邀请码：QY2026')}}
const recs=i=>(state.records[i]||[]).slice().sort((a,b)=>a.date.localeCompare(b.date));const latest=i=>recs(i).at(-1);const change=i=>{let a=recs(i);return a.length>1?a.at(-1).weight-a[0].weight:null};const signed=n=>(n>0?'+':'')+n.toFixed(2);
function spark(i){let a=recs(i),vals=a.map(x=>x.weight);if(a.length<2)return '<span class="small">数据不足</span>';let lo=Math.min(...vals)-.1,hi=Math.max(...vals)+.1;return `<svg class="spark" viewBox="0 0 80 32" aria-label="体重迷你趋势"><polyline points="${vals.map((v,j)=>`${j/(a.length-1)*76+2},${28-(v-lo)/(hi-lo)*24}`).join(' ')}" fill="none" stroke="${['#cf4938','#7083bd','#b66d8e','#9177b0'][i%4]}" stroke-width="2"/></svg>`}
function memberStatus(i){let l=latest(i);if(l?.date===state.today)return '今日已记录';let last=l?.date||state.members[i].join||state.room.start;return last&&last<=dateAdd(state.today,-3)?'多日未记录':'今日未记录'}
function groupProgress(){const total=state.room.days,last=end(),started=state.today>=state.room.start,finished=state.room.status==='ended'||state.today>last,day=finished?total:started?dayCount():0,percent=Math.max(0,Math.min(100,day/total*100)),remaining=Math.max(0,total-day),label=finished?'已结束':!started?'尚未开始':remaining===0?'今天结束':'还有 '+remaining+' 天';return `<section class="card group-deadline"><div class="deadline-heading"><span>截止日期</span><strong>${last} <span>23:59</span></strong></div><div class="period-progress-meta"><span>${finished?'本期已完成':started?'第 '+day+' / '+total+' 天':'共 '+total+' 天'}</span><span>${label}</span></div><div class="period-progress-track" role="progressbar" aria-label="本期时间进度" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="${day}" aria-valuetext="${started?'第 '+day+' 天，共 '+total+' 天。':''}${label}"><span style="width:${percent}%"></span></div></section>`}
function groupPage(){let r=state.room;return `${head(esc(r.name),'',`<button class="btn secondary" onclick="invite()" ${state.members.length>=8?'disabled':''}>邀请 ↗</button>`)}${groupProgress()}<section class="card"><div class="row section-head"><h2>成员数据</h2></div>${state.members.map((m,i)=>{let l=latest(i),c=change(i),status=memberStatus(i);return `<div class="member"><div class="row"><button class="person" style="padding:0;text-align:left" onclick="memberDetail(${i})" aria-label="查看${esc(m.name)}的数据分析">${avatar(m,i)}<div><div class="member-name">${esc(m.name)}${i===0?'（我）':''}</div><div class="member-status">${badge(status,status==='多日未记录'?'amber':status==='今日未记录'?'neutral':'')}</div></div></button><div class="member-details"><div class="member-spark" aria-label="${esc(m.name)}的体重趋势">${spark(i)}</div><div><div class="member-weight">${l?l.weight.toFixed(2):'—'} <small>kg</small></div><small>${c===null?'数据不足':`${c>0?'已增重':'已减重'} ${Math.abs(c).toFixed(2)} kg`}</small></div></div></div></div>`}).join('')}</section>`}
function memberDetail(i){if(!state.members[i])return;selected=i;range=28;closeModal();go('analysis')}
function recordPage(){if(state.room.status!=='active')return `${head('体重记录')}<div class="card empty"><h2>${state.room.status==='ended'?'本期已结束':'本期还未开始'}</h2><p class="sub">${state.room.status==='ended'?'历史记录仍可在基础分析里查看。':'完成组队和准备后，就可以开始记录。'}</p><br>${btn('返回小组',"go('group')")}</div>`;return `<div class="form-shell">${head('记录体重')}<form class="card record-form" onsubmit="event.preventDefault();saveRecord()"><div class="weight-entry"><div class="unit-toggle" role="group" aria-label="体重单位"><button type="button" id="unitKg" class="${unit==='kg'?'active':''}" aria-pressed="${unit==='kg'}" onclick="switchUnit('kg')">公斤</button><button type="button" id="unitJin" class="${unit==='斤'?'active':''}" aria-pressed="${unit==='斤'}" onclick="switchUnit('斤')">斤</button></div><div class="entry-line"><input id="weight" class="record-input" type="text" inputmode="decimal" autocomplete="off" placeholder="00.00" aria-label="体重" value="${latest(0)?.date===state.today?(latest(0).weight*(unit==='斤'?2:1)).toFixed(2):''}"><span id="unitLabel">${unit==='kg'?'公斤':'斤'}</span></div><div id="recordError" class="error"></div></div><section class="record-target" aria-label="本期目标"><div class="target-heading"><h3>本期目标</h3><span class="target-period">${state.room.days} 天</span></div><div class="target-reading"><strong id="targetValue">${(me().target*(unit==='斤'?2:1)).toFixed(2)}</strong><span id="targetUnit">${unit==='kg'?'公斤':'斤'}</span></div><div class="target-meta"><span class="target-dot" aria-hidden="true"></span>${state.room.intensity}强度</div></section><div class="record-save">${btn('保存记录',"",'full')}</div></form></div>`}
function switchUnit(u){if(unit===u)return;let v=Number($('#weight').value);if(v)$('#weight').value=(u==='斤'?v*2:v/2).toFixed(2);unit=u;$('#unitLabel').textContent=u==='kg'?'公斤':'斤';$('#unitKg').setAttribute('aria-pressed',u==='kg');$('#unitJin').setAttribute('aria-pressed',u==='斤');$('#unitKg').classList.toggle('active',u==='kg');$('#unitJin').classList.toggle('active',u==='斤');$('#targetValue').textContent=(me().target*(u==='斤'?2:1)).toFixed(2);$('#targetUnit').textContent=u==='kg'?'公斤':'斤'}
function saveRecord(){if(state.room.status!=='active'){toast('当前不可新增记录');return}let w=Number($('#weight').value)/(unit==='斤'?2:1),d=state.today;if(!Number.isFinite(w)||w<=0){$('#recordError').textContent='请输入大于 0 的有效体重';return}let record={date:d,weight:+w.toFixed(2),backfill:false},old=recs(0).find(x=>x.date===d);if(old)modal('确认修改记录',`<p class="record-confirm-date">${d.replaceAll('-', ' / ')}</p><div class="record-change"><div class="record-change-before"><span>原记录</span><strong>${old.weight.toFixed(2)}<small>kg</small></strong></div><span class="record-change-arrow" aria-hidden="true">→</span><div class="record-change-after"><span>修改后</span><strong>${record.weight.toFixed(2)}<small>kg</small></strong></div></div><p class="record-change-note">统计和图表将同步更新。</p>`,btn('确认修改',`commitRecord(${esc(JSON.stringify(record))})`,'full')+`<button class="cancel" onclick="closeModal()">取消</button>`,{hideClose:true,className:'record-confirm-modal'});else commitRecord(record)}
function commitRecord(r){state.records[0]=(state.records[0]||[]).filter(x=>x.date!==r.date);state.records[0].push(r);closeModal();go('group');toast('记录已保存，图表已更新')}
const colors=['#cf4938','#7083bd','#b66d8e','#9177b0'];
function filtered(i){let anchor=state.room.status==='ended'?end():state.today;return recs(i).filter(x=>x.date>=dateAdd(anchor,-range+1)&&x.date<=anchor)}
function chart(){const a=filtered(selected);if(!a.length)return `<div class="empty"><h3>还没有记录</h3>${selected===0&&state.room.status==='active'?btn('去记录',"go('record')",'soft'):''}</div>`;const values=a.map(x=>x.weight),lo=Math.floor((Math.min(...values)-.3)*2)/2,hi=Math.ceil((Math.max(...values)+.3)*2)/2,start=a[0].date,last=a.at(-1).date,span=Math.max(1,(new Date(last)-new Date(start))/86400000),narrow=window.innerWidth<=760,W=narrow?360:600,H=narrow?260:216,R=W-30,B=H-38,X=d=>48+((new Date(d)-new Date(start))/86400000)/span*(R-48),Y=v=>B-(v-lo)/(hi-lo)*(B-30),color=colors[selected%4];const grid=Array.from({length:5},(_,j)=>{const v=lo+(hi-lo)*j/4;return `<line x1="48" x2="${R}" y1="${Y(v)}" y2="${Y(v)}" stroke="#e8e8e8" stroke-dasharray="3 4"/><text x="36" y="${Y(v)+4}" text-anchor="end">${v.toFixed(1)}</text>`}).join('');return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="原始体重折线图，${a.length} 条记录，点按数据点查看日期与数值"><text x="48" y="14">体重 / kg</text>${grid}<polyline points="${a.map(x=>X(x.date)+','+Y(x.weight)).join(' ')}" fill="none" stroke="${color}" stroke-width="2.5"/>${a.map(x=>`<circle tabindex="0" role="button" aria-label="${x.date} ${x.weight.toFixed(2)} kg" cx="${X(x.date)}" cy="${Y(x.weight)}" r="4" fill="${color}" onclick="toast('${x.date} · ${x.weight.toFixed(2)} kg${x.backfill?' · 补录':''}')" onkeydown="if(event.key==='Enter')this.dispatchEvent(new MouseEvent('click'))"><title>${x.date} · ${x.weight.toFixed(2)} kg</title></circle>`).join('')}<text x="48" y="${H-9}">${start.slice(5)}</text><text x="${R}" y="${H-9}" text-anchor="end">${last.slice(5)}</text></svg><div class="chart-legend"><span><i style="background:${color}"></i>${esc(state.members[selected].name)}</span></div>`}
function analysisPage(){selected=Math.max(0,Math.min(selected,state.members.length-1));const a=filtered(selected),n=a.length,anchor=state.room.status==='ended'?end():state.today,start=[dateAdd(anchor,-range+1),state.members[selected].join||state.room.start].sort().at(-1),den=Math.max(1,Math.round((new Date(anchor)-new Date(start))/86400000)+1);return `${backButton('group','返回小组')}${head(esc(state.members[selected].name)+'的数据分析')}<section class="card"><div class="row chart-heading"><div class="tabs">${[7,28].map(n=>`<button class="${range===n?'active':''}" onclick="range=${n};render()">近 ${n} 天</button>`).join('')}</div></div>${chart()}</section><div class="stats"><div class="stat"><small>记录天数</small><strong>${n}<span class="unit">天</span></strong></div><div class="stat"><small>记录覆盖率</small><strong>${Math.round(n/den*100)}<span class="unit">%</span></strong></div></div><button type="button" class="card record-details-entry" onclick="openRecordDetails()" aria-haspopup="dialog"><span class="record-details-label"><span class="record-details-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M8 4h8a2 2 0 0 1 2 2v14H6V6a2 2 0 0 1 2-2Z M9 9h6 M9 13h6 M9 17h4"/></svg></span>记录明细</span><span class="record-details-trailing"><small>${n} 条</small><svg class="record-details-chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m9 6 6 6-6 6"/></svg></span></button>`}
function openRecordDetails(all=false){const records=(all?recs(0):filtered(selected)).slice().reverse();modal('记录明细',`<div class="record-details-scroll">${records.length?`<table class="record-list"><thead><tr><th scope="col">日期</th><th scope="col">状态</th><th scope="col">体重 / kg</th></tr></thead><tbody>${records.map(x=>`<tr><td>${x.date}</td><td>${x.backfill?'补录':'自报'}</td><td>${x.weight.toFixed(2)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">该区间还没有记录</div>'}</div>`,btn('关闭',"closeModal()",'secondary full'),{hideClose:true,className:'record-details-modal'});$('#overlay .modal-shade').classList.add('record-details-sheet')}
const groupColors=['#cf4938','#6b80c6','#b96491','#9471bc','#32978f','#c18a35','#628d50','#5c91b2'];
function groupSeries(){const anchor=state.room.status==='ended'?end():state.today,start=dateAdd(anchor,-groupRange+1);return state.members.map((m,i)=>{const all=recs(i),rows=all.filter(x=>x.date>=start&&x.date<=anchor),first=all[0]?.weight;return {m,i,rows:rows.map(x=>({...x,value:groupMetric==='weight'?x.weight:groupMetric==='percent'?(x.weight-first)/first*100:x.weight-first})),color:groupColors[i%groupColors.length]}})}
function groupChart(){const series=groupSeries(),anchor=state.room.status==='ended'?end():state.today,start=[dateAdd(anchor,-groupRange+1),state.room.start].sort().at(-1),points=series.flatMap(x=>x.rows);if(!points.length)return '<div class="empty">该区间还没有记录</div>';const vals=points.map(x=>x.value),min=Math.min(...vals),max=Math.max(...vals),pad=Math.max((max-min)*.15,groupMetric==='weight'?.5:.1),lo=min-pad,hi=max+pad,W=360,H=260,L=48,R=344,T=30,B=222,span=Math.max(1,(new Date(anchor)-new Date(start))/86400000),X=d=>L+(new Date(d)-new Date(start))/86400000/span*(R-L),Y=v=>B-(v-lo)/(hi-lo)*(B-T),label=groupMetric==='weight'?'体重 / kg':groupMetric==='percent'?'较首条变化 / %':'较首条变化 / kg';return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="小组成员${esc(label)}对比图"><text x="${L}" y="14">${label}</text>${Array.from({length:5},(_,j)=>{const v=lo+(hi-lo)*j/4;return `<line x1="${L}" x2="${R}" y1="${Y(v)}" y2="${Y(v)}" stroke="#e8e8e8" stroke-dasharray="3 4"/><text x="38" y="${Y(v)+4}" text-anchor="end">${v.toFixed(1)}</text>`}).join('')}${lo<0&&hi>0?`<line x1="${L}" x2="${R}" y1="${Y(0)}" y2="${Y(0)}" stroke="#bbb" stroke-dasharray="4 4"/>`:''}${series.map(x=>`<polyline points="${x.rows.map(r=>X(r.date)+','+Y(r.value)).join(' ')}" fill="none" stroke="${x.color}" stroke-width="2"/>${x.rows.map(r=>`<circle cx="${X(r.date)}" cy="${Y(r.value)}" r="3" fill="${x.color}"><title>${esc(x.m.name)} · ${r.date} · ${r.value.toFixed(2)} ${groupMetric==='percent'?'%':'kg'}</title></circle>`).join('')}`).join('')}<text x="${L}" y="251">${start.slice(5)}</text><text x="${R}" y="251" text-anchor="end">${anchor.slice(5)}</text></svg><div class="group-values">${series.map(x=>{const r=x.rows.at(-1);return `<div class="group-value"><span class="group-value-name"><i style="background:${x.color}"></i>${esc(x.m.name)}</span><strong>${r?(groupMetric!=='weight'&&r.value>0?'+':'')+r.value.toFixed(2):'—'}${r?`<small>${groupMetric==='percent'?'%':'kg'}</small>`:''}</strong></div>`}).join('')}</div>`}
function mePage(){return `${head('小组数据')}<section class="card group-comparison"><div class="row group-chart-top"><h2>成员对比</h2><div class="tabs">${[7,28].map(n=>`<button class="${groupRange===n?'active':''}" onclick="groupRange=${n};render()">近 ${n} 天</button>`).join('')}</div></div><div class="group-metric" aria-label="对比维度">${[['weight','体重'],['change','体重变化'],['percent','变化比例']].map(([v,t])=>`<button aria-pressed="${groupMetric===v}" class="${groupMetric===v?'active':''}" onclick="groupMetric='${v}';render()">${t}</button>`).join('')}</div>${groupChart()}</section>`}
function info(t,s){modal(t,`<p>${s}</p>`,btn('知道了',"closeModal()",'full'))}
function support(){modal('数据申请 / 账号支持','<p>你可以申请数据取回、删除或账号支持。</p><label class="field"><span class="field-label">申请说明</span><textarea id="supportText" placeholder="描述你的需求"></textarea></label>',btn('提交',"closeModal();toast('申请已提交')",'full'))}
function reviewPage(){let ranking=state.members.map((m,i)=>({m,i,n:recs(i).length,coverage:recs(i).length/(Math.round((new Date(end())-new Date(m.join||state.room.start))/86400000)+1)})).sort((a,b)=>b.coverage-a.coverage);return `${head('本期复盘','本期已结束 · '+state.room.start+' — '+end(),badge('本期复盘'))}<section class="card record-hero"><h2>本期记录概况</h2><p class="sub">${state.members.length} 位朋友 · ${state.room.days} 天的约定<br>共留下 ${Object.values(state.records).reduce((s,a)=>s+a.length,0)} 条记录</p></section><section class="card"><div class="row"><h2>小组记录参与</h2></div><p class="sub">按记录覆盖率排序，同值并列。不按减重速度排名。</p>${ranking.map((x,j)=>{let den=Math.round((new Date(end())-new Date(x.m.join||state.room.start))/86400000)+1;return `<div class="member row"><button type="button" class="person review-member" onclick="memberDetail(${x.i})" aria-label="查看${esc(x.m.name)}的数据分析"><span class="rank">${ranking.findIndex(y=>y.coverage===x.coverage)+1}</span>${avatar(x.m,x.i)}<div><strong>${esc(x.m.name)}</strong><p class="sub">记录 ${x.n} / ${den} 天</p></div></button><strong>${Math.round(x.n/den*100)}%</strong></div>`}).join('')}</section><div style="margin-top:12px">${btn('再组一期',"draft={name:'',intro:'',days:14,intensity:'低'};go('create')",'full')}</div>`}
function loadDemo(){state={...blank(),today:'2026-10-12',remindRead:false,room:{name:'晚饭后散步小队',intro:'不急着改变，先把每一天记录下来。',days:28,intensity:'低',start:'2026-10-01',status:'active',demo:true},members:[{name:'林可',ready:true,height:168,weight:70,target:69.44,join:'2026-10-01'},{name:'阿宁',ready:true,target:64.44,join:'2026-10-01'},{name:'小周',ready:true,target:77.44,join:'2026-10-01'},{name:'小林',ready:true,target:59.44,join:'2026-10-10'}],records:{}};let data=[[70,69.9,70.1,69.8,69.7,null,69.8,69.6,69.7,69.5,69.6],[65,65.1,64.9,65,64.8,64.9,64.7,64.8,64.6,64.7,64.5,64.6],[78,78.1,null,77.9,78,77.8,77.9,77.7],[]];data.forEach((a,i)=>state.records[i]=a.flatMap((w,j)=>w===null?[]:[{date:dateAdd('2026-10-01',j),weight:w}]));state.records[3]=[{date:'2026-10-10',weight:60},{date:'2026-10-11',weight:60.1}];selected=0;go('group')}
function finishDemo(){if(!state.room?.demo)loadDemo();closeModal();state.room.status='ended';state.today='2026-10-29';state.remindRead=true;go('group')}
function resetAll(){closeModal();state=blank();draft={name:'',intro:'',days:14,intensity:'低'};save();render();toast('数据已重置')}
function scene(v){if(v==='full'||v==='invalid'){inviteState=v;go('invite');return}loadDemo();closeModal();state.remindRead=true;if(v==='empty')state.records[0]=[];if(v==='single')state.records[0]=[{date:'2026-10-12',weight:70}];go('analysis')}
function previewScreen(page){closeModal();if(page==='lobby'){go(state.room?.status==='lobby'?'lobby':'create');return}if(['home','create','join'].includes(page)){go(page);return}if(!state.room?.start)loadDemo();state.remindRead=true;go(page)}
if(!['home','create','join','invite','lobby','group','record','analysis','me'].includes(state.page))state.page=state.room?.start?'analysis':state.room?'lobby':'home';
for(const key of ['premium','order','analysisStart','analysisEnd'])delete state[key];
const previewPage=new URLSearchParams(location.search).get('preview');if(['home','create','join'].includes(previewPage))state.page=previewPage;
render();
